{
  "headline": "Oxaliplatin is not on FDA's shortage list as of 2026-10-21; our supply traces to Baxter Healthcare Corporation product labeled with FAREVA Unterach GmbH for Sandoz Inc.",
  "headline_cites": ["D3", "E1", "E3"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows oxaliplatin is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale General holds 57 vials of oxaliplatin 5 mg/mL, 10 mL (NDC 43066001401) from Baxter Healthcare Corporation, providing 20 days of supply at current use.",
      "cites": ["E1", "D1"]
    },
    {
      "text": "Corvale Lakeside holds 8 vials of the same product, providing 8.6 days of supply.",
      "cites": ["E2", "D2"]
    },
    {
      "text": "The product label names FAREVA Unterach GmbH for Sandoz Inc. as the manufacturing plant.",
      "cites": ["E3"]
    },
    {
      "text": "FDA's shortage list records two discontinuations for oxaliplatin: Fresenius Kabi USA, LLC posted 2026-02-25 and Jiangsu Hengrui Pharmaceuticals Co., Ltd. posted 2026-06-29, both listed as To Be Discontinued.",
      "cites": ["E4", "E5"]
    },
    {
      "text": "The recommended action is to transfer 6 vials of 5 mg/mL, 10 mL from Corvale General to Corvale Lakeside, which would leave Corvale General with 18 days and bring Corvale Lakeside to 15 days of supply.",
      "cites": ["D4"]
    }
  ]
}
